@font-face {
  font-family: "Inter";
  src: url("Inter.ttf") format("truetype");
  font-weight: 100 900;
  font-style: normal;
  font-display: block;
}

:root {
  --bg: #0F1226;
  --accent: #7C5CFF;
  --ink: #FFFFFF;
  --muted: #A7ADCB;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", sans-serif;
  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
}

/* ---------- ambient background ---------- */
.card {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  isolation: isolate;
}

.glow {
  position: absolute;
  border-radius: 50%;
  z-index: -2;
  pointer-events: none;
  filter: blur(10px);
}

.grid-lines {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    linear-gradient(to right, rgba(255,255,255,.028) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255,255,255,.028) 1px, transparent 1px);
  background-size: 72px 72px;
  mask-image: radial-gradient(130% 110% at 20% 0%, #000 0%, transparent 72%);
  -webkit-mask-image: radial-gradient(130% 110% at 20% 0%, #000 0%, transparent 72%);
}

/* ---------- header ---------- */
.header {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.header img {
  display: block;
  flex-shrink: 0;
}

.rule {
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.22);
}

.event-name {
  font-weight: 700;
  text-transform: uppercase;
  white-space: nowrap;
  color: #FFFFFF;
}

/* ---------- portrait ---------- */
.portrait {
  position: relative;
  flex-shrink: 0;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  background-image: url("portrait.png");
  background-size: cover;
  background-position: center 42%;
  background-repeat: no-repeat;
  background-color: #D6C7B3;
}

.portrait::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.28),
    0 0 0 var(--ring, 6px) rgba(124, 92, 255, 0.95);
}

/* ---------- speaker ---------- */
.speaker-name {
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.12;
  color: #FFFFFF;
}

.speaker-role {
  font-weight: 500;
  color: var(--muted);
  line-height: 1.3;
}

/* ---------- title ---------- */
.kicker {
  display: flex;
  align-items: center;
  gap: 0.7em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--accent);
  white-space: nowrap;
}

.kicker::before {
  content: "";
  width: 2.2em;
  height: 3px;
  border-radius: 2px;
  background: var(--accent);
  flex-shrink: 0;
}

.title {
  font-weight: 700;
  letter-spacing: -0.022em;
  line-height: 1.14;
  text-wrap: balance;
  color: #FFFFFF;
}

.title em {
  font-style: normal;
  color: var(--accent);
}

/* ---------- meta ---------- */
.meta {
  font-weight: 500;
  color: var(--muted);
  line-height: 1.35;
}

.meta b { color: #FFFFFF; font-weight: 600; }

/* ---------- button ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6em;
  background: var(--accent);
  color: #FFFFFF;
  font-weight: 700;
  letter-spacing: 0.005em;
  border-radius: 999px;
  white-space: nowrap;
  box-shadow: 0 10px 34px rgba(124, 92, 255, 0.38);
  align-self: flex-start;
}

.btn svg { display: block; flex-shrink: 0; }

